# minimax-pmoves.ps1 -- launch `minimax` with pmoves/env.shared loaded
# ===========================================================================
# Auto-generated PowerShell twin of minimax-pmoves.sh. Same shell
# pattern as the hand-written claude-pmoves.ps1 / crush-pmoves.ps1:
#   1. Resolve repo root from $PSScriptRoot
#   2. Source env.shared via two-pass assign-then-expand
#   3. Apply per-CLI blocklist + name bridges
#   4. Hand off to the binary with any passed args
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File deploy\provision\minimax-pmoves.ps1 [args]
#   .\minimax-pmoves.cmd                     # Windows Explorer double-click
#   install-minimax-pmoves-command.ps1 ; minimax-pmoves     # profile function
#
# Purpose: MiniMax Code with the pmoves.bootstrap/v1 client profile (roster + service tags + routing + constraints)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$envf = if ($env:PMOVES_ENV_SHARED) { $env:PMOVES_ENV_SHARED } else { Join-Path $root 'pmoves\env.shared' }

# Mavis SDK env strip -- dot-source pmoves/scripts/mavis_sdk_env.ps1
# (PowerShell twin of mavis_sdk_env.sh) and apply the per-CLI needs check.
# The strip happens BEFORE env.shared is read, because the SHELL env (parent
# process) and env.shared (PMOVES fleet creds) are INDEPENDENT layers -- the
# blocklist below handles env.shared, this strip handles SHELL vars that came
# in from the operator's parent process (typically the Mavis
# `~/.claude/settings.json` env block).
#
# WHY IT IS OUTSIDE THE `if (Test-Path $envf)` BRANCH. The bash twin runs
# this strip UNCONDITIONALLY, before env.shared loading. Nesting it inside
# the env.shared branch meant the one scenario where the strip matters most
# -- env.shared missing, launcher still launching -- was EXACTLY the scenario
# where it never ran, letting ANTHROPIC_BASE_URL / ANTHROPIC_AUTH_TOKEN from
# the operator's parent process sail into the launched binary and quietly
# point its backend at an Anthropic endpoint. The platform the Mavis desktop
# client actually lives on is the one that lost the guard. Two independent
# layers means one being absent must not disable the other.
$mavis_helper = Join-Path $root 'pmoves\scripts\mavis_sdk_env.ps1'
if (Test-Path $mavis_helper) {
    . $mavis_helper
    Strip-MavisSdkEnvFor -CliName 'minimax'
} else {
    Write-Warning "[minimax-pmoves] mavis_sdk_env.ps1 not found at $mavis_helper -- Mavis SDK env may bleed into the launched session."
}

if (Test-Path $envf) {
    # Per-CLI blocklist (mirrors DEFAULT_BLOCKLIST_BY_TOOL in pmoves_launcher_generator.py).
    # These control the minimax SDK itself, not MCP creds -- sourcing them would
    # clobber session state or force API billing.
    $blocklist = @(
        'ANTHROPIC_API_KEY',
        'ANTHROPIC_AUTH_TOKEN',
        'ANTHROPIC_BASE_URL',
        'MINIMAX_API_KEY'
    ) -replace '\*', '.*'

    # Pass 1: read KEY=VALUE verbatim into an ordered map, skipping blocklisted keys.
    $vars = [ordered]@{}
    foreach ($line in Get-Content -LiteralPath $envf) {
        if ($line -match '^\s*#') { continue }
        if ($line -match '^\s*$') { continue }
        $eq = $line.IndexOf('=')
        if ($eq -lt 1) { continue }
        $key = $line.Substring(0, $eq).Trim()
        $blocked = $false
        foreach ($pat in $blocklist) { if ($key -match "^$pat$") { $blocked = $true; break } }
        if ($blocked) { continue }
        $val = ($line.Substring($eq + 1) -replace '\r$', '')
        if ($key) { $vars[$key] = $val }
    }
    # Pass 2: expand ${VAR} and ${VAR:-default} against the map (bounded iteration).
    for ($pass = 0; $pass -lt 5; $pass++) {
        $changed = $false
        foreach ($k in @($vars.Keys)) {
            $curKey = $k
            $varPat = '\$' + [char]123 + '([A-Za-z_][A-Za-z0-9_]*)(?::-([^' + [char]125 + ']*))?' + [char]125
            $resolved = [regex]::Replace($vars[$k], $varPat, {
                param($m)
                $name = $m.Groups[1].Value
                $repl = $null
                if ($name -ne $curKey) {
                    if ($vars.Contains($name) -and $vars[$name] -ne '' -and $vars[$name] -notmatch $varPat) {
                        $repl = $vars[$name]
                    } else {
                        $envv = [Environment]::GetEnvironmentVariable($name)
                        if ($envv) { $repl = $envv }
                    }
                }
                if ($null -ne $repl) { $repl }
                elseif ($m.Groups[2].Success) { $m.Groups[2].Value }
                else { '' }
            })
            if ($resolved -ne $vars[$k]) { $vars[$k] = $resolved; $changed = $true }
        }
        if (-not $changed) { break }
    }
    $n = 0
    foreach ($k in $vars.Keys) { [Environment]::SetEnvironmentVariable($k, $vars[$k], 'Process'); $n++ }
    Write-Host "[minimax-pmoves] loaded $n vars from $envf"
    $script:launcherSession = "minimax-pmoves.ps1 ($n vars)"
} else {
    Write-Warning "[minimax-pmoves] $envf not found -- MCP creds may be missing."
    $script:launcherSession = "minimax-pmoves.ps1 (env file NOT FOUND)"
}

[Environment]::SetEnvironmentVariable('PMOVES_LAUNCHER_SESSION', $script:launcherSession, 'Process')

# --- NAME BRIDGES (mirror bash twin) ----------------------------------------
# (no name bridges for this CLI)

# --- MCP ROSTER GENERATION ------------------------------------------------
# WHY THIS BLOCK EXISTS. minimax-pmoves does NOT read the tracked
# `.claude/mcp.json` roster that the sibling stacks (claude / kimi / kilo /
# hermes / crush) load -- MiniMax Code reads its OWN `~/.minimax/mcp.json`,
# and that file is RENDERED by pmoves/tools/mcp_config_generator.py from the
# shared inventory plus this client's bootstrap profile.
#
# Nothing else in the launch path rendered it. The launcher sourced
# env.shared and handed off to the binary, so a fresh host -- or any host
# whose ~/.minimax/mcp.json still carried only the `composio` entry -- started
# the client with NO PMOVES MCP servers at all. That is a SILENT degradation:
# no error, no non-zero exit, just a client that cannot reach the fleet.
#
# ORDERING IS LOAD-BEARING.
#   * AFTER env.shared -- the roster expands ${VAR} from the env.shared
#     values (NATS_URL, the cipher token, the cross-node hostnames). A roster
#     rendered before env.shared would carry literal ${VAR} text.
#   * BEFORE the handoff -- the client reads ~/.minimax/mcp.json at startup.
#
# FAILURE PATH: FAIL CLOSED. If the generator cannot run, the client would
# start with a stale or missing roster and no error at all -- the precise
# failure this block exists to prevent. So a generator failure is an explicit
# ERROR plus a non-zero exit. PMOVES_ALLOW_MISSING_ROSTER=1 is the explicit,
# greppable opt-out.
#
# --endpoint local: the client is a DESKTOP client on this host, and the
# services it declares node-local are published on THIS host's loopback.
# The generator's "fleet" default would point them at ${TS_Z890} instead.
$rosterGen = Join-Path $root 'pmoves\tools\mcp_config_generator.py'
if ($env:PMOVES_ALLOW_MISSING_ROSTER) {
    Write-Warning "[minimax-pmoves] PMOVES_ALLOW_MISSING_ROSTER is set -- skipping MCP roster generation."
} else {
    $rosterWhy = ''
    $pyHelper = Join-Path $root 'pmoves\scripts\pm-python.ps1'
    if (-not (Test-Path -LiteralPath $rosterGen -PathType Leaf)) {
        $rosterWhy = "the generator is missing: $rosterGen"
    } elseif (-not (Test-Path -LiteralPath $pyHelper -PathType Leaf)) {
        $rosterWhy = "pm-python.ps1 is missing: $pyHelper"
    } else {
        . $pyHelper
        # -Probe yaml: mcp_config_generator.py reads this client's bootstrap
        # profile, which is YAML. An interpreter that cannot import it would
        # fail the render with a traceback instead of a clean refusal.
        $pyArgv = Get-PmovesPythonArgv -Root $root -Probe 'yaml'
        if (-not $pyArgv) {
            $rosterWhy = "no python interpreter that can import yaml (tried `$env:PMOVES_PYTHON, $root\pmoves\.venv-pmoves, py -3, python3, python)"
        } else {
            # @(...) is load-bearing: a one-element slice is a bare STRING, and
            # splatting a string passes its characters (see pm-python.ps1).
            $pyPre = @(if ($pyArgv.Count -gt 1) { $pyArgv[1..($pyArgv.Count - 1)] })
            $exe = $pyArgv[0]
            # A generator failure is DATA here -- it becomes $rosterWhy -- not
            # a script abort, so the native non-zero exit is captured instead
            # of thrown. $ErrorActionPreference is 'Stop' in this script.
            $prevEap = $ErrorActionPreference
            $ErrorActionPreference = 'Continue'
            $rosterRc = 0
            try {
                & $exe @pyPre $rosterGen --client minimax --endpoint local
                $rosterRc = $LASTEXITCODE
            } catch {
                $rosterRc = 1
            } finally {
                $ErrorActionPreference = $prevEap
            }
            if ($rosterRc -ne 0) {
                $rosterWhy = "mcp_config_generator.py --client minimax --endpoint local exited $rosterRc"
            }
        }
    }
    if ($rosterWhy) {
        Write-Error "[minimax-pmoves] ERROR: could not generate the MCP roster -- $rosterWhy" -ErrorAction Continue
        Write-Error "[minimax-pmoves]        the client would start with NO PMOVES MCP servers." -ErrorAction Continue
        Write-Error "[minimax-pmoves]        to launch anyway: `$env:PMOVES_ALLOW_MISSING_ROSTER=1 ..." -ErrorAction Continue
        exit 1
    }
    Write-Host "[minimax-pmoves] MCP roster generated for client 'minimax' (endpoint 'local')."
}

# --- LAUNCH ---------------------------------------------------------------
& minimax @args
